// FactOutcomes — one row per ANALYTIC outcome event (exact duplicate rows excluded).
// Source  : RepoRoot & "data\processed\outcomes_clean.csv"  (generated by analysis/audit_datasets.py)
// Grain   : outcome_event_id (primary key, unique)
// Expected: 173,749 rows (173,775 source rows - 26 exact duplicate excess copies; DECISION_LOG D-009)
// Rules   : outcome_datetime is the source wall-clock time; the "-05:00" offset is kept as text metadata in
//           outcome_tz_offset and is NEVER applied (D-008). Midnight / offset rows are date-only records.
//           outcome_status_provisional is a PROVISIONAL grouping, not the City live-release rate (D-014).
let
    SourcePath = RepoRoot & "data\processed\outcomes_clean.csv",
    Raw = Csv.Document(File.Contents(SourcePath), [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Raw, [PromoteAllScalars = false]),

    ExpectedColumns = {
        "outcome_event_id", "source_row", "animal_id", "outcome_datetime", "outcome_date", "outcome_tz_offset",
        "outcome_time_is_date_only", "outcome_is_midnight", "monthyear_consistent", "date_of_birth",
        "dob_after_outcome", "name", "name_has_asterisk", "outcome_type", "outcome_type_missing", "outcome_subtype",
        "outcome_group", "outcome_status_provisional", "animal_type", "sex_upon_outcome", "age_upon_outcome_raw",
        "age_upon_outcome_days", "age_upon_outcome_invalid", "age_from_dob_days", "breed", "color",
        "is_exact_duplicate", "is_same_id_timestamp_conflict"},
    Selected = Table.SelectColumns(Promoted, ExpectedColumns, MissingField.Error),
    BlankToNull = Table.TransformColumns(Selected, {}, each if _ = "" then null else _),

    ParseDate = (t as nullable text) as nullable date =>
        if t = null then null else Date.FromText(t, [Format = "yyyy-MM-dd", Culture = "en-US"]),
    ParseDateTime = (t as nullable text) as nullable datetime =>
        if t = null then null else DateTime.FromText(t, [Format = "yyyy-MM-dd HH:mm:ss", Culture = "en-US"]),
    ParseNumber = (t as nullable text) as nullable number =>
        if t = null then null else Number.FromText(t, "en-US"),
    ParseInt = (t as nullable text) as nullable number =>
        if t = null then null else Int64.From(Number.FromText(t, "en-US")),
    ParseFlag = (t as nullable text) as nullable logical =>
        if t = null then null else if t = "1" then true else if t = "0" then false
        else error Error.Record("InvalidFlag", "Expected 1/0 flag value", t),

    TextColumns = {
        "outcome_event_id", "animal_id", "outcome_tz_offset", "name", "outcome_type", "outcome_subtype",
        "outcome_group", "outcome_status_provisional", "animal_type", "sex_upon_outcome", "age_upon_outcome_raw",
        "breed", "color"},
    TypedText = Table.TransformColumnTypes(BlankToNull, List.Transform(TextColumns, each {_, type text})),

    Typed = Table.TransformColumns(TypedText, {
        {"source_row", ParseInt, Int64.Type},
        {"outcome_datetime", ParseDateTime, type nullable datetime},
        {"outcome_date", ParseDate, type nullable date},
        {"date_of_birth", ParseDate, type nullable date},
        {"age_upon_outcome_days", ParseNumber, type nullable number},
        {"age_from_dob_days", ParseInt, Int64.Type},
        {"outcome_time_is_date_only", ParseFlag, type nullable logical},
        {"outcome_is_midnight", ParseFlag, type nullable logical},
        {"monthyear_consistent", ParseFlag, type nullable logical},
        {"dob_after_outcome", ParseFlag, type nullable logical},
        {"name_has_asterisk", ParseFlag, type nullable logical},
        {"outcome_type_missing", ParseFlag, type nullable logical},
        {"age_upon_outcome_invalid", ParseFlag, type nullable logical},
        {"is_exact_duplicate", ParseFlag, type nullable logical},
        {"is_same_id_timestamp_conflict", ParseFlag, type nullable logical}}),

    AnalyticEvents = Table.SelectRows(Typed, each [is_exact_duplicate] = false),
    Keyed = Table.AddKey(AnalyticEvents, {"outcome_event_id"}, true)
in
    Keyed
